<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';Auth::requireLogin();$edit=null;if(isset($_GET['edit'])){$st=$db->prepare('SELECT * FROM media WHERE id=?');$st->execute([(int)$_GET['edit']]);$edit=$st->fetch();}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{if(($_POST['action']??'save')==='delete'){$db->prepare('DELETE FROM media WHERE id=?')->execute([(int)$_POST['id']]);flash('success','Mídia excluída.');}else{$id=(int)($_POST['id']??0);$file=upload_image('file_path',$_POST['current_file']?:null);$data=[trim($_POST['title']),$_POST['media_type'],nullable_int($_POST['category_id']),$file,trim($_POST['video_url']),trim($_POST['description']),$_POST['event_date']?:null,isset($_POST['active'])?1:0];if($id){$data[]=$id;$db->prepare('UPDATE media SET title=?,media_type=?,category_id=?,file_path=?,video_url=?,description=?,event_date=?,active=? WHERE id=?')->execute($data);}else{$db->prepare('INSERT INTO media(title,media_type,category_id,file_path,video_url,description,event_date,active) VALUES(?,?,?,?,?,?,?,?)')->execute($data);}flash('success','Mídia salva.');}}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('multimedia.php');}
$cats=$db->query('SELECT id,name FROM age_categories WHERE active=1 ORDER BY sort_order,name')->fetchAll();$rows=$db->query('SELECT m.*,c.name category_name FROM media m LEFT JOIN age_categories c ON c.id=m.category_id ORDER BY event_date DESC,id DESC')->fetchAll();require __DIR__.'/_header.php';?>
<div class="page-title"><div><h1>Multimídia</h1><p>Wallpapers, fotos e vídeos do dia a dia e das competições.</p></div></div><div class="admin-grid"><form method="post" enctype="multipart/form-data" class="panel form-stack"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??''))?>"><input type="hidden" name="current_file" value="<?=e($edit['file_path']??'')?>"><h2><?=$edit?'Editar':'Nova'?> mídia</h2><label>Título<input name="title" required value="<?=e($edit['title']??'')?>"></label><label>Tipo<select name="media_type"><?php foreach(['wallpaper'=>'Wallpaper','foto'=>'Foto','video'=>'Vídeo'] as $v=>$l):?><option value="<?=$v?>" <?=($edit['media_type']??'foto')===$v?'selected':''?>><?=$l?></option><?php endforeach;?></select></label><label>Categoria<select name="category_id"><option value="">Todas</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=($edit['category_id']??null)==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></label><label>Imagem<input type="file" name="file_path" accept="image/*"></label><label>URL do vídeo<input type="url" name="video_url" value="<?=e($edit['video_url']??'')?>" placeholder="YouTube, Vimeo ou outra URL"></label><label>Data<input type="date" name="event_date" value="<?=e($edit['event_date']??'')?>"></label><label>Descrição<textarea name="description" rows="3"><?=e($edit['description']??'')?></textarea></label><label class="check"><input type="checkbox" name="active" <?=($edit['active']??1)?'checked':''?>> Publicar</label><button class="btn primary">Salvar</button></form><div class="panel"><div class="table-wrap"><table><thead><tr><th>Título</th><th>Tipo</th><th>Categoria</th><th>Data</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['title'])?></td><td><?=e($r['media_type'])?></td><td><?=e($r['category_name']??'Todas')?></td><td><?=format_date($r['event_date'])?></td><td class="actions"><a href="?edit=<?=$r['id']?>">Editar</a><form method="post" onsubmit="return confirm('Excluir?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button>Excluir</button></form></td></tr><?php endforeach;?></tbody></table></div></div></div><?php require __DIR__.'/_footer.php';?>
